<template>
  <div class="space-y-6" data-testid="resource-archives">
    <div class="flex flex-wrap items-center justify-between gap-3"><h2 class="text-xl font-semibold">{{ t('backupCenter.archives.title') }}</h2><UButton color="neutral" variant="outline" icon="i-heroicons-arrow-path" :loading="loading" @click="load">{{ t('backupCenter.reload') }}</UButton></div>
    <UAlert v-if="error" color="error" :title="error" />
    <UAlert v-if="notice" color="success" :title="notice" />
    <UAlert v-if="overview?.pending_transfers" color="warning" :title="t('backupCenter.archives.pending', { count: overview.pending_transfers })" />
    <UCard>
      <template #header><div class="flex flex-wrap items-center justify-between gap-3"><h3 class="font-semibold">{{ t('backupCenter.archives.policies') }}</h3><UButton icon="i-heroicons-plus" :disabled="busy || !overview?.sources.length" @click="openPolicy()">{{ t('backupCenter.newPolicy') }}</UButton></div></template>
      <p v-if="!overview?.policies.length" class="py-6 text-center text-sm text-gray-500">{{ t('backupCenter.noPolicies') }}</p>
      <div class="space-y-4"><article v-for="p in overview?.policies" :key="p.id" class="rounded-xl border border-gray-200 p-4 dark:border-gray-700" data-testid="archive-policy">
        <div class="flex items-center justify-between gap-3"><h4 class="font-medium">{{ p.name }}</h4><UBadge variant="subtle" :color="p.enabled ? 'success' : 'warning'">{{ t(p.enabled ? 'backupCenter.workspace.scheduleOn' : 'backupCenter.workspace.scheduleOff') }}</UBadge></div>
        <dl class="mt-4 grid gap-3 text-sm sm:grid-cols-4"><div><dt class="text-xs text-gray-500">{{ t('backupCenter.archives.source') }}</dt><dd class="mt-1">{{ sourceLabel(p.source_id) }}</dd></div><div><dt class="text-xs text-gray-500">{{ t('backupCenter.workspace.frequency') }}</dt><dd class="mt-1">{{ t('backupCenter.workspace.everyMinutes', { count: p.interval_minutes }) }}</dd></div><div><dt class="text-xs text-gray-500">{{ t('backupCenter.archives.localRetention') }}</dt><dd class="mt-1">{{ t('backupCenter.keepDaysCount', { days: p.retention_days, count: p.retention_count }) }}</dd></div><div><dt class="text-xs text-gray-500">{{ t('backupCenter.archives.remoteTarget') }}</dt><dd class="mt-1">{{ targetLabel(p.target_id) }}</dd></div></dl>
        <div class="mt-4 flex flex-wrap justify-end gap-2"><UButton size="sm" color="neutral" variant="ghost" :disabled="busy" @click="openPolicy(p)">{{ t('backupCenter.edit') }}</UButton><UButton size="sm" :color="p.enabled ? 'warning' : 'primary'" variant="outline" :disabled="busy" @click="perform(() => toggle(p))">{{ t(p.enabled ? 'backupCenter.workspace.disableSchedule' : 'backupCenter.workspace.enableSchedule') }}</UButton><UButton size="sm" :disabled="busy" @click="openRun(p)">{{ t('backupCenter.archives.runNow') }}</UButton></div>
      </article></div>
    </UCard>
    <UCard>
      <template #header><div class="flex flex-wrap items-center justify-between gap-3"><h3 class="font-semibold">{{ t('backupCenter.archives.targets') }}</h3><UButton color="neutral" variant="outline" icon="i-heroicons-plus" :disabled="busy || !overview?.credentials.length" @click="openTarget()">{{ t('backupCenter.archives.newTarget') }}</UButton></div></template>
      <p v-if="!overview?.credentials.length" class="text-sm text-amber-700 dark:text-amber-400">{{ t('backupCenter.archives.credentialsMissing') }}</p>
      <div class="space-y-4"><article v-for="target in overview?.targets" :key="target.id" class="rounded-xl border border-gray-200 p-4 dark:border-gray-700"><div class="flex flex-wrap items-center justify-between gap-3"><div><h4 class="font-medium">{{ target.name }}</h4><p class="mt-1 break-all font-mono text-xs">{{ target.user }}@{{ target.host }}:{{ target.port }} · {{ target.directory }}</p><p class="mt-1 text-xs text-gray-500">{{ t('backupCenter.archives.credential') }}: {{ target.credential_ref }}</p></div><div class="flex gap-2"><UButton size="sm" color="neutral" variant="ghost" :disabled="busy" @click="openTarget(target)">{{ t('backupCenter.edit') }}</UButton><UButton size="sm" color="neutral" variant="outline" :disabled="busy" @click="perform(() => test(target))">{{ t('backupCenter.archives.testTarget') }}</UButton></div></div></article></div>
    </UCard>
    <UCard>
      <template #header><div class="flex flex-wrap items-center justify-between gap-3"><h3 class="font-semibold">{{ t('backupCenter.archives.jobs') }}</h3><UButton color="warning" variant="outline" :disabled="busy" @click="confirm = { kind: 'cleanup' }">{{ t('backupCenter.cleanup') }}</UButton></div></template>
      <p v-if="!overview?.jobs.length" class="py-6 text-center text-sm text-gray-500">{{ t('backupCenter.noJobs') }}</p>
      <div class="space-y-4"><article v-for="job in overview?.jobs" :key="job.id" class="rounded-xl border border-gray-200 p-4 dark:border-gray-700" data-testid="archive-job">
        <div class="flex flex-wrap items-center justify-between gap-3"><div><h4 class="font-medium">{{ sourceLabel(job.source_id) }}</h4><p class="mt-1 text-xs text-gray-500">{{ timeLabel(job.created_at) }}</p></div><div class="flex gap-2"><UBadge variant="subtle" :color="job.status === 'success' ? 'success' : job.status === 'failed' ? 'error' : 'neutral'">{{ stateLabel(job.status) }}</UBadge><UBadge variant="subtle" :color="job.remote_state === 'success' ? 'success' : job.remote_state === 'failed' ? 'error' : 'neutral'">{{ remoteLabel(job.remote_state) }}</UBadge></div></div>
        <p v-if="job.status === 'running'" class="mt-3 text-sm" role="status">{{ t('backupCenter.archives.processing') }} · {{ job.file_count }}</p>
        <p v-if="job.error || job.remote_error" class="mt-3 break-words text-sm text-red-600 dark:text-red-400">{{ job.error || job.remote_error }}</p>
        <dl class="mt-4 grid gap-3 text-sm sm:grid-cols-4"><div><dt class="text-xs text-gray-500">{{ t('backupCenter.archives.fileCount') }}</dt><dd class="mt-1">{{ job.file_count }}</dd></div><div><dt class="text-xs text-gray-500">{{ t('backupCenter.archives.totalSize') }}</dt><dd class="mt-1">{{ sizeLabel(job.size_bytes) }}</dd></div><div><dt class="text-xs text-gray-500">{{ t('backupCenter.archives.newSize') }}</dt><dd class="mt-1">{{ sizeLabel(job.new_bytes) }}</dd></div><div><dt class="text-xs text-gray-500">{{ t('backupCenter.source') }}</dt><dd class="mt-1 break-all font-mono">{{ job.database || '—' }}</dd></div></dl>
        <details class="mt-4 text-xs"><summary class="cursor-pointer text-primary-600 dark:text-primary-400">{{ t('backupCenter.archives.details') }}</summary><dl class="mt-3 space-y-3 rounded-lg bg-gray-50 p-3 dark:bg-gray-800/50"><div><dt>{{ t('backupCenter.archives.jobID') }}</dt><dd class="mt-1 break-all font-mono">{{ job.id }}</dd></div><div><dt>{{ t('backupCenter.archives.manifest') }}</dt><dd class="mt-1 break-all font-mono">{{ overview?.directory }}/jobs/{{ job.id }}.json</dd></div><div v-if="job.remote_path"><dt>{{ t('backupCenter.archives.remotePath') }}</dt><dd class="mt-1 break-all font-mono">{{ job.remote_path }}</dd></div><div v-if="job.remote_state === 'failed'"><dt>{{ t('backupCenter.archives.attempts') }}</dt><dd>{{ job.attempts }} · {{ timeLabel(job.retry_at) }}</dd></div><p v-for="warning in job.warnings" :key="warning" class="text-amber-700 dark:text-amber-400">{{ warning }}</p></dl></details>
        <div class="mt-4 flex flex-wrap justify-end gap-2"><UBadge v-if="job.protected" color="success" variant="subtle">{{ t('backupCenter.protected') }}</UBadge><UButton v-if="canDownload(job)" size="sm" color="neutral" variant="outline" :disabled="busy" @click="perform(() => service.download(job.id))">{{ t('backupCenter.archives.download') }}</UButton><UButton v-if="job.status === 'success'" size="sm" color="neutral" variant="ghost" :disabled="busy" @click="perform(() => protect(job))">{{ t(job.protected ? 'backupCenter.unprotect' : 'backupCenter.protect') }}</UButton><UButton v-if="job.status === 'success' && job.remote_state === 'failed'" size="sm" color="warning" variant="outline" :disabled="busy" @click="perform(() => retry(job))">{{ t('backupCenter.archives.retry') }}</UButton><UButton v-if="canDownload(job) && job.kind === 'media'" size="sm" :disabled="busy" @click="confirm = { kind: 'restore', job }">{{ t('backupCenter.archives.restore') }}</UButton></div>
      </article></div>
    </UCard>
    <UCard v-if="overview?.restores.length"><template #header><h3 class="font-semibold">{{ t('backupCenter.archives.restores') }}</h3></template><div class="space-y-4"><article v-for="r in overview.restores" :key="r.id" class="rounded-xl border border-gray-200 p-4 dark:border-gray-700"><div class="flex flex-wrap justify-between gap-3"><p class="break-all font-mono text-xs">{{ r.directory }}</p><UBadge :color="r.status === 'success' ? 'success' : r.status === 'failed' ? 'error' : 'neutral'" variant="subtle">{{ stateLabel(r.status) }}</UBadge></div><p v-if="r.database_copy_name" class="mt-3 break-all text-sm">{{ t('backupCenter.archives.databaseProgress') }}: {{ r.database_copy_name }}</p><p v-if="r.error" class="mt-3 text-sm text-red-600">{{ r.error }}</p><UButton v-if="r.status !== 'running' && r.status !== 'deleted'" class="mt-3" size="sm" color="error" variant="ghost" :disabled="busy" @click="deleteRestore = r; deleteID = ''">{{ t('backupCenter.archives.deleteRestore') }}</UButton></article></div></UCard>
    <UCard><template #header><h3 class="font-semibold">{{ t('backupCenter.archives.sources') }}</h3></template><p class="mb-4 break-all font-mono text-xs">{{ t('backupCenter.archives.storageRoot') }}: {{ overview?.directory || '—' }}</p><div class="space-y-3"><div v-for="source in overview?.sources" :key="source.id" class="border-t border-gray-100 pt-3 dark:border-gray-800"><div class="flex justify-between gap-2"><p class="text-sm font-medium">{{ source.name }}</p><UBadge :color="source.ready ? 'success' : 'warning'" variant="subtle">{{ t(source.ready ? 'backupCenter.archives.ready' : 'backupCenter.notReady') }}</UBadge></div><p class="mt-1 break-all font-mono text-xs text-gray-500">{{ source.directory }}</p><p v-if="source.problem" class="mt-1 text-xs text-amber-700 dark:text-amber-400">{{ source.problem }}</p></div></div></UCard>

    <UModal v-if="policyOpen" v-model:open="policyOpen" :title="t('backupCenter.newPolicy')" :description="t('backupCenter.archives.policyHint')" :ui="{ content: 'max-w-2xl' }"><template #body><UForm id="archive-policy-form" :state="policyForm" :schema="policySchema" class="space-y-4" @submit="perform(savePolicy)"><UFormField name="name" :label="t('backupCenter.policyName')" required><UInput v-model="policyForm.name" class="w-full" /></UFormField><UFormField name="source_id" :label="t('backupCenter.archives.source')" required><USelect v-model="policyForm.source_id" :items="sourceOptions" class="w-full" /></UFormField><div class="grid gap-4 sm:grid-cols-2"><UFormField name="interval_minutes" :label="t('backupCenter.archives.intervalMinutes')"><UInput v-model.number="policyForm.interval_minutes" type="number" min="1" class="w-full" /></UFormField><UFormField name="target_id" :label="t('backupCenter.archives.remoteTarget')"><USelect v-model="policyForm.target_id" :items="targetOptions" class="w-full" /></UFormField><UFormField name="retention_days" :label="t('backupCenter.archives.localDays')"><UInput v-model.number="policyForm.retention_days" type="number" min="1" max="3650" class="w-full" /></UFormField><UFormField name="retention_count" :label="t('backupCenter.archives.localCount')"><UInput v-model.number="policyForm.retention_count" type="number" min="1" max="10000" class="w-full" /></UFormField><UFormField name="remote_retention_days" :label="t('backupCenter.archives.remoteDays')"><UInput v-model.number="policyForm.remote_retention_days" type="number" min="1" max="3650" class="w-full" /></UFormField><UFormField name="remote_retention_count" :label="t('backupCenter.archives.remoteCount')"><UInput v-model.number="policyForm.remote_retention_count" type="number" min="1" max="10000" class="w-full" /></UFormField></div><UCheckbox v-if="selectedSource?.kind === 'media'" v-model="policyForm.include_database" :label="t('backupCenter.archives.includeDatabase')" /><p v-if="modalError" class="text-sm text-red-600">{{ modalError }}</p></UForm></template><template #footer><div class="flex w-full justify-end gap-2"><UButton color="neutral" variant="ghost" @click="policyOpen = false">{{ t('backupCenter.cancel') }}</UButton><UButton type="submit" form="archive-policy-form" :loading="busy">{{ t('backupCenter.save') }}</UButton></div></template></UModal>
    <UModal v-if="targetOpen" v-model:open="targetOpen" :title="t('backupCenter.archives.newTarget')" :description="t('backupCenter.archives.targetHint')"><template #body><UForm id="archive-target-form" :state="targetForm" :schema="targetSchema" class="space-y-4" @submit="perform(saveTarget)"><UFormField name="name" :label="t('backupCenter.archives.targetName')"><UInput v-model="targetForm.name" class="w-full" /></UFormField><div class="grid gap-4 sm:grid-cols-2"><UFormField name="host" :label="t('backupCenter.copies.host')"><UInput v-model="targetForm.host" class="w-full" /></UFormField><UFormField name="port" :label="t('backupCenter.copies.port')"><UInput v-model.number="targetForm.port" type="number" min="1" max="65535" class="w-full" /></UFormField></div><UFormField name="user" :label="t('backupCenter.copies.username')"><UInput v-model="targetForm.user" class="w-full" /></UFormField><UFormField name="directory" :label="t('backupCenter.archives.targetDirectory')"><UInput v-model="targetForm.directory" placeholder="/data/powerx-archives" class="w-full" /></UFormField><UFormField name="credential_ref" :label="t('backupCenter.archives.credential')"><USelect v-model="targetForm.credential_ref" :items="overview?.credentials || []" class="w-full" /></UFormField><p v-if="modalError" class="text-sm text-red-600">{{ modalError }}</p></UForm></template><template #footer><div class="flex w-full justify-end gap-2"><UButton color="neutral" variant="ghost" @click="targetOpen = false">{{ t('backupCenter.cancel') }}</UButton><UButton type="submit" form="archive-target-form" :loading="busy">{{ t('backupCenter.save') }}</UButton></div></template></UModal>
    <UModal v-if="confirm" :open="!!confirm" :title="t(confirm?.kind === 'restore' ? 'backupCenter.archives.restore' : confirm?.kind === 'cleanup' ? 'backupCenter.cleanup' : 'backupCenter.archives.runNow')" :description="t(confirm?.kind === 'restore' ? 'backupCenter.archives.restoreHint' : confirm?.kind === 'cleanup' ? 'backupCenter.archives.cleanupHint' : 'backupCenter.archives.runHint')" @update:open="open => { if (!open) confirm = null }"><template #body><div class="space-y-4"><p v-if="confirm?.kind === 'run'" class="font-medium">{{ confirm.policy.name }} · {{ sourceLabel(confirm.policy.source_id) }}</p><p v-if="confirm?.kind === 'restore'" class="break-all font-mono text-xs">{{ confirm.job.id }}</p><UCheckbox v-if="confirm?.kind === 'restore'" v-model="allowOlder" :label="t('backupCenter.archives.olderConsent')" /><p v-if="modalError" class="text-sm text-red-600">{{ modalError }}</p></div></template><template #footer><div class="flex w-full justify-end gap-2"><UButton color="neutral" variant="ghost" :disabled="busy" @click="confirm = null">{{ t('backupCenter.cancel') }}</UButton><UButton :loading="busy" @click="perform(confirmAction)">{{ t('backupCenter.confirm') }}</UButton></div></template></UModal>
    <UModal v-if="deleteRestore" :open="!!deleteRestore" :title="t('backupCenter.archives.deleteRestore')" :description="t('backupCenter.archives.deleteHint')" @update:open="open => { if (!open) deleteRestore = undefined }"><template #body><div class="space-y-4"><p class="break-all font-mono text-xs">{{ deleteRestore?.id }}</p><UFormField :label="t('backupCenter.archives.typeRestoreID')"><UInput v-model="deleteID" class="w-full" /></UFormField><p v-if="modalError" class="text-sm text-red-600">{{ modalError }}</p></div></template><template #footer><div class="flex w-full justify-end gap-2"><UButton color="neutral" variant="ghost" @click="deleteRestore = undefined">{{ t('backupCenter.cancel') }}</UButton><UButton color="error" :disabled="deleteID !== deleteRestore?.id" :loading="busy" @click="perform(removeRestore)">{{ t('backupCenter.archives.deleteRestore') }}</UButton></div></template></UModal>
  </div>
</template>
<script setup lang="ts">
import { computed, onMounted, onBeforeUnmount, reactive, ref, watch } from 'vue';
import * as v from 'valibot';
import { useArchiveOpsService, type ArchiveOverview, type ArchivePolicy, type ArchiveTarget, type ArchiveJob, type ArchiveRestore } from '~/composables/api/services/archiveOpsService';
import { formatBackupTime } from '~/utils/backup-display';
const { t, locale } = useI18n(); const service = useArchiveOpsService();
const overview = ref<ArchiveOverview>(); const error = ref(''); const notice = ref(''); const modalError = ref(''); const loading = ref(false); const busy = ref(false);
const policyOpen = ref(false); const targetOpen = ref(false); const allowOlder = ref(false);
const confirm = ref<{ kind: 'run'; policy: ArchivePolicy; key: string } | { kind: 'restore'; job: ArchiveJob } | { kind: 'cleanup' } | null>(null);
const deleteRestore = ref<ArchiveRestore>(); const deleteID = ref('');
const policyDefaults = (): ArchivePolicy => ({ name: '', source_id: '', interval_minutes: 60, retention_days: 7, retention_count: 168, remote_retention_days: 90, remote_retention_count: 2160, target_id: '', include_database: true, enabled: false });
const targetDefaults = (): ArchiveTarget => ({ name: '', host: '', port: 22, user: '', directory: '/data/powerx-archives', credential_ref: '' });
const policyForm = reactive(policyDefaults()); const targetForm = reactive(targetDefaults());
const positive = (max: number) => v.pipe(v.number(), v.integer(), v.minValue(1), v.maxValue(max));
const policySchema = v.object({ name: v.pipe(v.string(), v.trim(), v.minLength(1), v.maxLength(128)), source_id: v.pipe(v.string(), v.minLength(1)), interval_minutes: positive(525600), retention_days: positive(3650), retention_count: positive(10000), remote_retention_days: positive(3650), remote_retention_count: positive(10000), target_id: v.string(), include_database: v.boolean(), enabled: v.boolean() });
const targetSchema = v.object({ name: v.pipe(v.string(), v.trim(), v.minLength(1)), host: v.pipe(v.string(), v.minLength(1)), port: positive(65535), user: v.pipe(v.string(), v.minLength(1)), directory: v.pipe(v.string(), v.regex(/^\/(?:[A-Za-z0-9_.-]+\/)*[A-Za-z0-9_.-]+$/)), credential_ref: v.pipe(v.string(), v.minLength(1)) });
const selectedSource = computed(() => overview.value?.sources.find(source => source.id === policyForm.source_id));
watch(() => policyForm.source_id, () => { if (selectedSource.value?.kind !== 'media') policyForm.include_database = false; });
const sourceOptions = computed(() => (overview.value?.sources || []).map(source => ({ value: source.id, label: source.name })));
const targetOptions = computed(() => [{ value: '', label: t('backupCenter.archives.localOnly') }, ...(overview.value?.targets || []).map(target => ({ value: target.id!, label: target.name }))]);
const sourceLabel = (id: string) => overview.value?.sources.find(source => source.id === id)?.name || id;
const targetLabel = (id?: string) => overview.value?.targets.find(target => target.id === id)?.name || t('backupCenter.archives.localOnly');
const sizeLabel = (size: number) => size < 1024 ? `${size} B` : size < 1048576 ? `${(size / 1024).toFixed(1)} KiB` : size < 1073741824 ? `${(size / 1048576).toFixed(1)} MiB` : `${(size / 1073741824).toFixed(1)} GiB`;
const timeLabel = (time?: string) => formatBackupTime(time, String(locale?.value || 'zh-CN'));
const stateLabel = (state: string) => ['running', 'success', 'failed', 'pruned', 'deleted'].includes(state) ? t(`backupCenter.archives.state.${state}`) : state;
const remoteLabel = (state: string) => ['pending', 'success', 'failed', 'not_requested'].includes(state) ? t(`backupCenter.archives.remoteState.${state}`) : state;
const canDownload = (job: ArchiveJob) => job.status === 'success' || (job.status === 'pruned' && job.remote_state === 'success');
const failure = (e: any) => { const data = e?.response?._data || e?.data; return [data?.message || e?.message || t('backupCenter.failed'), data?.error].filter(Boolean).join(' · '); };
let timer: ReturnType<typeof setTimeout> | undefined; let disposed = false; let revision = 0;
async function load() { if (loading.value || disposed) return; clearTimeout(timer); loading.value = true; const requestedRevision = revision; try { const data = await service.overview(); if (!disposed && requestedRevision === revision) { overview.value = data; error.value = ''; } } catch (e) { if (!disposed && requestedRevision === revision) error.value = failure(e); } finally { loading.value = false; if (!disposed && (overview.value?.jobs.some(job => job.status === 'running' || job.remote_state === 'pending') || overview.value?.restores.some(r => r.status === 'running'))) timer = setTimeout(load, 2500); } }
async function perform(action: () => Promise<unknown>) { if (busy.value) return; busy.value = true; error.value = ''; modalError.value = ''; notice.value = ''; try { await action(); } catch (e) { error.value = failure(e); modalError.value = error.value; } finally { busy.value = false; } }
function openPolicy(policy?: ArchivePolicy) { delete policyForm.id; Object.assign(policyForm, policyDefaults(), { source_id: overview.value?.sources[0]?.id || '' }, policy || {}); modalError.value = ''; policyOpen.value = true; }
async function savePolicy() { const payload = { ...policyForm, include_database: selectedSource.value?.kind === 'media' && policyForm.include_database }; await service.savePolicy(payload); revision++; policyOpen.value = false; await load(); }
function openTarget(target?: ArchiveTarget) { delete targetForm.id; Object.assign(targetForm, targetDefaults(), { credential_ref: overview.value?.credentials[0] || '' }, target || {}); modalError.value = ''; targetOpen.value = true; }
async function saveTarget() { await service.saveTarget({ ...targetForm }); revision++; targetOpen.value = false; await load(); }
async function test(target: ArchiveTarget) { await service.testTarget(target.id!); notice.value = t('backupCenter.archives.targetVerified'); }
async function toggle(policy: ArchivePolicy) { await service.savePolicy({ ...policy, enabled: !policy.enabled }); revision++; await load(); }
async function retry(job: ArchiveJob) { await service.retry(job.id); revision++; await load(); }
async function protect(job: ArchiveJob) { await service.protect(job.id, !job.protected); revision++; await load(); }
function openRun(policy: ArchivePolicy) { confirm.value = { kind: 'run', policy, key: crypto.randomUUID() }; }
async function confirmAction() { if (!confirm.value) return; const action = confirm.value; if (action.kind === 'run') { const row = await service.run(action.policy.id!, action.key); revision++; if (overview.value) overview.value.jobs = [row, ...overview.value.jobs.filter(job => job.id !== row.id)]; } else if (action.kind === 'restore') { const row = await service.restore(action.job.id, allowOlder.value); revision++; if (overview.value) overview.value.restores.unshift(row); } else await service.cleanup(); confirm.value = null; await load(); }
watch(confirm, current => { allowOlder.value = false; modalError.value = ''; if (current?.kind === 'run' && !current.key) current.key = crypto.randomUUID(); });
async function removeRestore() { if (!deleteRestore.value || deleteID.value !== deleteRestore.value.id) return; await service.removeRestore(deleteRestore.value.id, deleteID.value); deleteRestore.value = undefined; await load(); }
onMounted(load); onBeforeUnmount(() => { disposed = true; clearTimeout(timer); });
</script>
